package com.rulecraft.decisionops.versions;
import static org.assertj.core.api.Assertions.*;import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.catalog.CatalogService.*;import com.rulecraft.decisionops.catalog.domain.*;import com.rulecraft.decisionops.expressions.DecisionExpressionService;import com.rulecraft.decisionops.expressions.DecisionExpressionService.ExpressionCommand;import com.rulecraft.decisionops.graph.DecisionGraphService;import com.rulecraft.decisionops.graph.DecisionGraphService.*;import com.rulecraft.decisionops.graph.domain.*;import com.rulecraft.decisionops.identity.domain.*;import com.rulecraft.decisionops.identity.persistence.UserAccountRepository;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectService;import com.rulecraft.decisionops.projects.domain.ProjectRole;import com.rulecraft.decisionops.tests.DecisionTestService;import com.rulecraft.decisionops.tests.DecisionTestService.TestCaseCommand;import com.rulecraft.decisionops.versions.DecisionVersionService.*;import com.rulecraft.decisionops.versions.domain.VersionValidationStatus;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.security.crypto.password.PasswordEncoder;import tools.jackson.databind.ObjectMapper;
@SpringBootTest class DecisionVersionIntegrationTest {@Autowired DecisionVersionService versions;@Autowired DecisionTestService decisionTests;@Autowired DecisionExpressionService expressions;@Autowired DecisionGraphService graphs;@Autowired CatalogService catalog;@Autowired ProjectService projects;@Autowired UserAccountRepository users;@Autowired PasswordEncoder passwords;@Autowired Clock clock;@Autowired ObjectMapper mapper;RuleCraftPrincipal admin;@BeforeEach void actor(){admin=new RuleCraftPrincipal(users.findForLogin("acme-rules","admin@example.test").orElseThrow(),"acme-rules");}
@Autowired com.rulecraft.decisionops.versions.persistence.DecisionVersionRepository versionRecords;
@Test void preservesPersistedLegacyFingerprintAcrossObjectMemberReordering() throws Exception {
    var fixture = fixture();
    var first = versions.capture(admin, fixture.projectId(), fixture.serviceId(), capture(fixture, "Original"));
    var stored = versionRecords.findById(first.id()).orElseThrow();
    var snapshot = mapper.readTree(stored.getSnapshotJson());
    var content = snapshot.path("content");
    var reordered = mapper.createObjectNode();
    content.propertyNames().stream().sorted(Comparator.reverseOrder()).forEach(key -> reordered.set(key, content.get(key)));
    ((tools.jackson.databind.node.ObjectNode) snapshot).set("content", reordered);
    var legacyHash = HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(mapper.writeValueAsBytes(reordered)));
    var legacy = versionRecords.saveAndFlush(new com.rulecraft.decisionops.versions.domain.DecisionVersion(
            admin.tenantId(), fixture.projectId(), fixture.serviceId(), UUID.randomUUID(), 2, "Legacy snapshot", null,
            first.validationStatus(), legacyHash, mapper.writeValueAsString(snapshot), first.sourceServiceVersion(),
            first.sourceGraphVersion(), admin.userId(), Instant.now(clock)));
    assertThat(versions.working(admin, fixture.projectId(), fixture.serviceId()).fingerprint()).isEqualTo(legacyHash);
    assertCode("RC-VERSION-NO-CHANGES", () -> versions.capture(admin, fixture.projectId(), fixture.serviceId(), capture(fixture, "Unchanged")));
    var expression = expressions.find(admin, fixture.projectId(), fixture.serviceId(), fixture.nodeId()).orElseThrow();
    expressions.update(admin, fixture.projectId(), fixture.serviceId(), fixture.nodeId(), new ExpressionCommand(expression.version(), "score >= 620"));
    assertThat(versions.working(admin, fixture.projectId(), fixture.serviceId()).fingerprint()).isNotEqualTo(legacyHash);
    assertThat(versionRecords.findById(legacy.getId()).orElseThrow().getFingerprint()).isEqualTo(legacyHash);
}
@Test void capturesImmutableVersionsAndProducesSemanticImplementationAndTestDiff(){var fixture=fixture();var first=versions.capture(admin,fixture.projectId(),fixture.serviceId(),capture(fixture,"Baseline"));assertThat(first.versionNumber()).isEqualTo(1);assertThat(first.validationStatus()).isEqualTo(VersionValidationStatus.VALID);var expression=expressions.find(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId()).orElseThrow();expressions.update(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId(),new ExpressionCommand(expression.version(),"score >= 650"));var test=decisionTests.list(admin,fixture.projectId(),fixture.serviceId()).getFirst();decisionTests.update(admin,fixture.projectId(),fixture.serviceId(),test.id(),new TestCaseCommand(test.version(),test.testKey(),test.name(),test.description(),test.inputs(),Map.of("approved",mapper.readTree("false"))));var second=versions.capture(admin,fixture.projectId(),fixture.serviceId(),capture(fixture,"Candidate"));var diff=versions.diff(admin,fixture.projectId(),fixture.serviceId(),first.id(),second.id());assertThat(second.versionNumber()).isEqualTo(2);assertThat(diff.changes()).extracting("category").contains(ChangeCategory.IMPLEMENTATION,ChangeCategory.TEST);assertThat(diff.behavioralCount()).isGreaterThan(0);assertThat(first.fingerprint()).isNotEqualTo(second.fingerprint());}
@Test void rejectsStaleAndUnchangedCaptureWhileRetryRemainsIdempotent(){var fixture=fixture();var request=UUID.randomUUID();var state=versions.working(admin,fixture.projectId(),fixture.serviceId());var command=new CaptureCommand(request,"Baseline",null,state.serviceVersion(),state.graphVersion(),state.fingerprint());var first=versions.capture(admin,fixture.projectId(),fixture.serviceId(),command);assertThat(versions.capture(admin,fixture.projectId(),fixture.serviceId(),command).id()).isEqualTo(first.id());assertCode("RC-VERSION-NO-CHANGES",()->versions.capture(admin,fixture.projectId(),fixture.serviceId(),capture(fixture,"Duplicate")));assertCode("RC-VERSION-STALE",()->versions.capture(admin,fixture.projectId(),fixture.serviceId(),new CaptureCommand(UUID.randomUUID(),"Stale",null,state.serviceVersion(),state.graphVersion()+1,state.fingerprint())));assertCode("RC-VERSION-DIFF-SELECTION",()->versions.diff(admin,fixture.projectId(),fixture.serviceId(),first.id(),first.id()));}
@Test void rejectsCaptureWhenImplementationChangedBehindUnchangedServiceAndGraphRevisions(){var fixture=fixture();var state=versions.working(admin,fixture.projectId(),fixture.serviceId());var expression=expressions.find(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId()).orElseThrow();expressions.update(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId(),new ExpressionCommand(expression.version(),"score >= 675"));assertCode("RC-VERSION-STALE",()->versions.capture(admin,fixture.projectId(),fixture.serviceId(),new CaptureCommand(UUID.randomUUID(),"Stale implementation",null,state.serviceVersion(),state.graphVersion(),state.fingerprint())));}
@Test void invalidDraftCanBeCapturedAndViewerCanReviewWithoutCapturing(){var fixture=fixture();var expression=expressions.find(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId()).orElseThrow();expressions.update(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId(),new ExpressionCommand(expression.version(),"score >="));var invalid=versions.capture(admin,fixture.projectId(),fixture.serviceId(),capture(fixture,"Invalid draft"));assertThat(invalid.validationStatus()).isEqualTo(VersionValidationStatus.INVALID);var now=Instant.now(clock);var viewerAccount=users.save(new UserAccount(admin.tenantId(),"version-viewer"+UUID.randomUUID()+"@example.test","Vera Version Viewer",passwords.encode("CorrectHorseBattery72!"),TenantRole.MEMBER,now));projects.upsertMember(admin,fixture.projectId(),viewerAccount.getId(),ProjectRole.VIEWER);var viewer=new RuleCraftPrincipal(viewerAccount,"acme-rules");assertThat(versions.list(viewer,fixture.projectId(),fixture.serviceId())).hasSize(1);assertCode("RC-PROJECT-EDIT-FORBIDDEN",()->versions.capture(viewer,fixture.projectId(),fixture.serviceId(),capture(fixture,"Forbidden")));var outsiderAccount=users.save(new UserAccount(admin.tenantId(),"version-outsider"+UUID.randomUUID()+"@example.test","Omar Version Outsider",passwords.encode("CorrectHorseBattery73!"),TenantRole.MEMBER,now));var outsider=new RuleCraftPrincipal(outsiderAccount,"acme-rules");assertCode("RC-PROJECT-NOT-FOUND",()->versions.list(outsider,fixture.projectId(),fixture.serviceId()));}
private CaptureCommand capture(Fixture fixture,String label){var state=versions.working(admin,fixture.projectId(),fixture.serviceId());return new CaptureCommand(UUID.randomUUID(),label,"Review evidence",state.serviceVersion(),state.graphVersion(),state.fingerprint());}private Fixture fixture(){var project=projects.create(admin,key("P"),"Version review",null);var service=catalog.createService(admin,project.id(),new DecisionServiceCommand(key("SVC"),"Eligibility versions",null,List.of(new FieldCommand("score","Score",builtin(BuiltinType.NUMBER),true)),List.of(new FieldCommand("approved","Approved",builtin(BuiltinType.BOOLEAN),true)),null));var graph=graphs.initialize(admin,project.id(),service.id());var nodeId=UUID.randomUUID();var input=port(GraphPortDirection.INPUT,"score",BuiltinType.NUMBER);var output=port(GraphPortDirection.OUTPUT,"approved",BuiltinType.BOOLEAN);var serviceInput=graph.nodes().stream().filter(node->node.kind()==GraphNodeKind.INPUT).findFirst().orElseThrow().ports().getFirst();var serviceOutput=graph.nodes().stream().filter(node->node.kind()==GraphNodeKind.OUTPUT).findFirst().orElseThrow().ports().getFirst();var nodes=new ArrayList<NodeCommand>();graph.nodes().forEach(node->nodes.add(command(node)));nodes.add(new NodeCommand(nodeId,"threshold","Approval threshold",GraphNodeKind.DECISION,null,300,100,List.of(input,output)));var savedGraph=graphs.update(admin,project.id(),service.id(),new GraphCommand(graph.version(),nodes,List.of(edge(serviceInput.id(),input.id()),edge(output.id(),serviceOutput.id()))));var expression=expressions.initialize(admin,project.id(),service.id(),nodeId);expressions.update(admin,project.id(),service.id(),nodeId,new ExpressionCommand(expression.version(),"score >= 700"));decisionTests.create(admin,project.id(),service.id(),new TestCaseCommand(null,"highScore","High score",null,Map.of("score",mapper.readTree("750")),Map.of("approved",mapper.readTree("true"))));return new Fixture(project.id(),service.id(),nodeId,service.version(),savedGraph.version());}
private CatalogService.TypeRefCommand builtin(BuiltinType type){return new CatalogService.TypeRefCommand(type,null);}private PortCommand port(GraphPortDirection direction,String key,BuiltinType type){return new PortCommand(UUID.randomUUID(),direction,key,key,new DecisionGraphService.TypeRefCommand(type,null),true,0);}private NodeCommand command(GraphNodeView node){return new NodeCommand(node.id(),node.nodeKey(),node.name(),node.kind(),node.serviceFieldKey(),node.positionX(),node.positionY(),node.ports().stream().map(port->new PortCommand(port.id(),port.direction(),port.portKey(),port.label(),port.type(),port.required(),port.position())).toList());}private EdgeCommand edge(UUID source,UUID target){return new EdgeCommand(UUID.randomUUID(),source,target);}private String key(String prefix){return prefix+UUID.randomUUID().toString().replace("-","").substring(0,8).toUpperCase();}private void assertCode(String code,Runnable action){assertThatThrownBy(action::run).isInstanceOf(DomainProblemException.class).extracting("code").isEqualTo(code);}private record Fixture(UUID projectId,UUID serviceId,UUID nodeId,long serviceVersion,long graphVersion){}
}
